package com.opensocket.aievent.database.persistence.a2a.operations;
import java.util.List;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.stereotype.Repository;import com.opensocket.aievent.core.a2a.*;
@Repository @ConditionalOnProperty(prefix="task",name="store",havingValue="MYBATIS") public class MybatisA2AOperationsReadRepository implements A2AOperationsReadRepository {private final A2AOperationsReadDao dao;public MybatisA2AOperationsReadRepository(A2AOperationsReadDao d){dao=d;}public List<A2AOperationsListItem> search(A2AOperationsSearchQuery q){return dao.search(q.tenantId(),q.requestStatus(),q.blockerCode(),q.operationalStage(),q.sourceDomainId(),q.targetDomainId(),q.text(),q.blockerOnly(),q.normalizedOffset(),q.cappedLimit(),q.normalizedSortBy(),q.normalizedSortDirection()).stream().map(this::toDomain).toList();}public long count(A2AOperationsSearchQuery q){return dao.count(q.tenantId(),q.requestStatus(),q.blockerCode(),q.operationalStage(),q.sourceDomainId(),q.targetDomainId(),q.text(),q.blockerOnly());}private A2AOperationsListItem toDomain(A2AOperationsListItemPo v){return new A2AOperationsListItem(v.getRequestId(),v.getRootTaskId(),v.getSourceTaskId(),v.getChildTaskId(),v.getSourceDomainId(),v.getTargetDomainId(),v.getRequestedTaskType(),v.getRequestStatus(),v.getOperationalStage(),v.getChildTaskStatus(),v.getDispatchStatus(),v.getRuntimeStatus(),v.getResultStatus(),v.getCancellationStatus(),v.getAggregationStatus(),v.getBlockerCode(),v.getBlockerMessage(),v.getRecommendedAction(),v.getCreatedAt(),v.getUpdatedAt(),v.getVersion());}public String mode(){return "MYBATIS_JOIN_PROJECTION";}}
